
import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { Alert, Box, Button, Snackbar } from "@mui/material";
import {
    getMyFriendsList,
    getFriendsSuggestion,
    acceptFriend,
    deleteFriendRequest,
    sendFriendsRequest,
} from "../services/friendService";
import { isAuthenticated } from "../services/authenticationService";
import Scene from "./Scene";
import FriendSideMenu from "../components/friends/FriendSideMenu";
import FriendsContent from "../components/friends/FriendsContent";
import {
    getMockFriendRequestSnapshot,
    getMockFriendSuggestionSnapshot,
} from "../mockData";


export default function Friends() {
    const [friends, setFriends] = useState(() => getMockFriendRequestSnapshot());
    const [suggestions, setSuggestion] = useState(() => getMockFriendSuggestionSnapshot());
    const [loading, setLoading] = useState(false);
    const [loadError, setLoadError] = useState(null);

    const navigate = useNavigate();
    const [snackbarOpen, setSnackbarOpen] = useState(false);
    const [snackbarMessage, setSnackbarMessage] = useState("");
    const [snackbarSeverity, setSnackbarSeverity] = useState("success");

    const loadFriends = async () => {
        try {
            setLoading(true);
            setLoadError(null);

            const [friendsRes, suggestionsRes] = await Promise.allSettled([
                getMyFriendsList(),
                getFriendsSuggestion(),
            ]);

            const failedRequests = [];

            if (friendsRes.status === "fulfilled") {
                setFriends(friendsRes.value.data.result || []);
            } else {
                setFriends([]);
                failedRequests.push("friends");
            }
            if (suggestionsRes.status === "fulfilled") {
                setSuggestion(suggestionsRes.value.data.result || []);
            } else {
                setSuggestion([]);
                failedRequests.push("suggestions");
            }

            if (failedRequests.length > 0) {
                setLoadError(
                    failedRequests.length === 2
                        ? "Unable to load friend data right now."
                        : "Some friend data could not be loaded."
                );
            }
        } catch (err) {
            console.error(err);
            setFriends([]);
            setSuggestion([]);
            setLoadError("Unable to load friend data right now.");
        } finally {
            setLoading(false);
        }
    };

    const handleSnackbarClose = (event, reason) => {
        if (reason === "clickaway") {
            return;
        }
        setSnackbarOpen(false);
    };

    useEffect(() => {
        if (!isAuthenticated()) {
            navigate("/login");
        }
    }, [navigate]);

    const handleConfirm = async (request) => {
        setFriends((prev) => prev.filter((item) => item.id !== request.id));
        try {
            console.log("Confirm friend request", request.id);
            await acceptFriend(request.relationId);
            setSnackbarMessage("Friend request accepted!");
            setSnackbarSeverity("success");
            setSnackbarOpen(true);
        } catch (err) {
            console.error(err);
            setFriends((prev) => [request, ...prev]);
            setSnackbarMessage("Failed to accept friend request.");
            setSnackbarSeverity("error");
            setSnackbarOpen(true);
        }
    };

    const handlePending = async (id) => {
        const removedSuggestion = suggestions.find((item) => item.userId === id);
        setSuggestion((prev) => prev.filter((item) => item.userId !== id));
        try {
            console.log("Peding friend request", id);
            await sendFriendsRequest(id);
            setSnackbarMessage("Friend request sent!");
            setSnackbarSeverity("success");
            setSnackbarOpen(true);
        } catch (err) {
            console.error(err);
            if (removedSuggestion) {
                setSuggestion((prev) => [removedSuggestion, ...prev]);
            }
            setSnackbarMessage("Failed to send friend request.");
            setSnackbarSeverity("error");
            setSnackbarOpen(true);
        }

    }

    const handleDelete = (id) => {
        console.log("Delete friend request", id);
        const removedRequest = friends.find((item) => item.id === id);
        setFriends((prev) => prev.filter((item) => item.id !== id));

        deleteFriendRequest(id)
            .then(() => {
                setSnackbarMessage("Friend request deleted.");
                setSnackbarSeverity("success");
                setSnackbarOpen(true);
            })
            .catch((err) => {
                console.error(err);
                if (removedRequest) {
                    setFriends((prev) => [removedRequest, ...prev]);
                }
                setSnackbarMessage("Failed to delete friend request.");
                setSnackbarSeverity("error");
                setSnackbarOpen(true);
            });
    };


    return (
        <Scene sideMenu={<FriendSideMenu />}>
            <Box
                sx={{
                    width: "100%",
                    maxWidth: 1280,
                    px: { xs: 2, sm: 3, md: 4 },
                    py: { xs: 2, sm: 3 },
                }}
            >
                <Snackbar
                    open={snackbarOpen}
                    autoHideDuration={6000}
                    onClose={handleSnackbarClose}
                    anchorOrigin={{ vertical: "top", horizontal: "right" }}
                    sx={{ mt: 8 }}
                >
                    <Alert
                        onClose={handleSnackbarClose}
                        severity={snackbarSeverity}
                        sx={{ width: "100%" }}
                    >
                        {snackbarMessage}
                    </Alert>
                </Snackbar>

                {loadError ? (
                    <Alert
                        severity="warning"
                        sx={{ mb: 3, borderRadius: 2 }}
                        action={
                            <Button color="inherit" size="small" onClick={loadFriends}>
                                Retry
                            </Button>
                        }
                    >
                        {loadError}
                    </Alert>
                ) : null}

                <FriendsContent
                    loading={loading}
                    friends={friends}
                    suggestions={suggestions}
                    onConfirm={handleConfirm}
                    onDelete={handleDelete}
                    onPending={handlePending}
                />
            </Box>
        </Scene >
    );
}
