import httpClient from "../configurations/httpClient";
import { API } from "../configurations/configuration";
import { getToken } from "./localStorageService";
import {
    acceptMockFriendRequest,
    deleteMockFriendRequest,
    getMockFriendRequestSnapshot,
    getMockFriendSuggestionSnapshot,
    sendMockFriendRequest,
} from "../mockData";

const USE_MOCK = window._env_?.REACT_APP_USE_MOCK === "true" || false;

const buildAuthHeaders = () => ({
    Authorization: `Bearer ${getToken()}`,
});

const withMockFallback = async (operation, request, fallback) => {
    if (USE_MOCK) {
        return fallback();
    }

    try {
        return await request();
    } catch (error) {
        console.warn(`[friendService] ${operation} failed`, error);
        return fallback();
    }
};

const wrapResult = (result) => ({
    data: {
        result,
    },
});

export const getMyFriendsList = async () => withMockFallback(
    "getMyFriendsList",
    () => httpClient.get(API.MY_FRIENDS, {
        headers: buildAuthHeaders(),
    }),
    () => wrapResult(getMockFriendRequestSnapshot())
);

export const getMyFriendRequest = async () => withMockFallback(
    "getMyFriendRequest",
    () => httpClient.get(API.MY_FRIEND_REQUESTS, {
        headers: buildAuthHeaders(),
    }),
    () => wrapResult(getMockFriendRequestSnapshot())
);

export const getFriendsSuggestion = async () => withMockFallback(
    "getFriendsSuggestion",
    () => httpClient.get(API.FRIENDS_SUGGESTION, {
        headers: buildAuthHeaders(),
    }),
    () => wrapResult(getMockFriendSuggestionSnapshot())
);

export const sendFriendsRequest = async (friendId) => withMockFallback(
    "sendFriendsRequest",
    () => httpClient.post(
        API.SEND_FRIEND_REQUEST,
        {
            status: "PENDING",
            participantIds: [friendId],
        },
        {
            headers: {
                ...buildAuthHeaders(),
                "Content-Type": "application/json",
            },
        }
    ),
    () => wrapResult(sendMockFriendRequest(friendId))
);

export const acceptFriend = async (relationId) => withMockFallback(
    "acceptFriend",
    () => httpClient.put(
        `${API.ACCEPT_FRIENDS}/${relationId}`,
        {},
        {
            headers: {
                ...buildAuthHeaders(),
                "Content-Type": "application/json",
            },
        }
    ),
    () => wrapResult(acceptMockFriendRequest(relationId))
);

export const createMessage = async (data) => withMockFallback(
    "createMessage",
    () => httpClient.post(
        API.CREATE_MESSAGE,
        {
            conversationId: data.conversationId,
            message: data.message,
        },
        {
            headers: {
                ...buildAuthHeaders(),
                "Content-Type": "application/json",
            },
        }
    ),
    () => wrapResult(data)
);

export const getMessages = async (conversationId) => withMockFallback(
    "getMessages",
    () => httpClient.get(`${API.GET_CONVERSATION_MESSAGES}?conversationId=${conversationId}`, {
        headers: buildAuthHeaders(),
    }),
    () => ({
        data: {
            result: [],
            conversationId,
        },
    })
);

export const deleteFriendRequest = async (id) => withMockFallback(
    "deleteFriendRequest",
    () => httpClient.delete(`${API.MY_FRIEND_REQUESTS}/${id}`, {
        headers: buildAuthHeaders(),
    }),
    () => wrapResult(deleteMockFriendRequest(id))
);