import { useEffect, useState, useRef } from "react";
import { useNavigate } from "react-router-dom";
import {
  Box,
  Card,
  CircularProgress,
  Typography,
  Dialog,
  Snackbar,
  Avatar,
  Alert,
  Button,
} from "@mui/material";
import { isAuthenticated } from "../services/authenticationService";
import Scene from "./Scene";
import { getMyFeed, markReadPosts } from "../services/feedService";
import { createPost, likePost } from "../services/postService";
import { getMockCurrentUser, getMockFeedSnapshot } from "../mockData";
import DraggableDialog from "../components/DialogCreatePost";
import SideMenu from "../components/header/SideMenu";

const currentUser = getMockCurrentUser();

const normalizePost = (post) => {
  const images = post.images || post.files?.map((file) => file.url).filter(Boolean) || [];

  return {
    ...post,
    postId: post.postId ?? post.id,
    name: post.name || post.authorName || currentUser.name,
    authorName: post.authorName || post.name || currentUser.name,
    avatarUrl: post.avatarUrl || post.avatar || currentUser.avatarUrl,
    avatar: post.avatar || post.avatarUrl || currentUser.avatarUrl,
    createdDate: post.createdDate || new Date().toISOString(),
    images,
    files: post.files?.length ? post.files : images.map((url) => ({ url })),
    likeCount: post.likeCount ?? 0,
    commentCount: post.commentCount ?? 0,
    liked: Boolean(post.liked),
  };
};

const buildOptimisticPost = (content, imagePreviews = []) => {
  const images = imagePreviews.map((image) => image.preview || image.url || "").filter(Boolean);

  return normalizePost({
    postId: `temp-${Date.now()}`,
    name: currentUser.name,
    authorName: currentUser.name,
    avatarUrl: currentUser.avatarUrl,
    avatar: currentUser.avatarUrl,
    timestamp: "Just now",
    createdDate: new Date().toISOString(),
    content,
    images,
    files: images.map((url) => ({ url })),
    likeCount: 0,
    commentCount: 0,
    liked: false,
  });
};



export default function Home() {
  const [posts, setPosts] = useState(() => getMockFeedSnapshot().map(normalizePost));
  const [loading, setLoading] = useState(false);
  const [feedError, setFeedError] = useState(null);
  const [hasMore, setHasMore] = useState(false);
  const observer = useRef();
  const [dialogOpen, setDialogOpen] = useState(false);
  const lastPostElementRef = useRef();
  const [newPostContent, setNewPostContent] = useState("");
  const [snackbarOpen, setSnackbarOpen] = useState(false);
  const [snackbarMessage, setSnackbarMessage] = useState("");
  const [snackbarSeverity, setSnackbarSeverity] = useState("success");
  const [readPosts, setReadPosts] = useState([]);
  const [selectedImages, setSelectedImages] = useState([]);
  const navigate = useNavigate();
  const readQueueRef = useRef([]);
  const [previewOpen, setPreviewOpen] = useState(false);
  const [previewImages, setPreviewImages] = useState([]);
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const checkpointRef = useRef(null);

  const [commentDialogOpen, setCommentDialogOpen] = useState(false);
  const [selectedPost, setSelectedPost] = useState(null);

  const handleOpenComments = (post) => {
    setSelectedPost(post);
    setCommentDialogOpen(true);
  };
  const handleCloseComments = () => {
    setCommentDialogOpen(false);
    setSelectedPost(null);
  };

  const handleImageClick = (images, index) => {
    setPreviewImages(images);
    setCurrentImageIndex(index);
    setPreviewOpen(true);
  };

  const handleClosePreview = () => {
    setPreviewOpen(false);
    setPreviewImages([]);
    setCurrentImageIndex(0);
  };

  const handleNextImage = () => {
    setCurrentImageIndex((prev) => (prev + 1) % previewImages.length);
  };

  const handlePrevImage = () => {
    setCurrentImageIndex((prev) => (prev - 1 + previewImages.length) % previewImages.length);
  };

  const handleLike = (postId) => {
    setPosts((prevPosts) =>
      prevPosts.map((post) => {
        if (post.postId !== postId) {
          return post;
        }

        const liked = !post.liked;
        return {
          ...post,
          liked,
          likeCount: Math.max(0, (post.likeCount || 0) + (liked ? 1 : -1)),
        };
      })
    );

    likePost(postId)
      .then((res) => {
        const likedPost = res?.data?.result;
        if (!likedPost) {
          return;
        }

        setPosts((prevPosts) =>
          prevPosts.map((post) =>
            post.postId === postId
              ? normalizePost({ ...post, ...likedPost })
              : post
          )
        );
      })
      .catch((err) => {
        console.error("Error liking post:", err);
      });
  };


  // Handle opening the popover
  const handleCreatePostClick = (event) => {
    setDialogOpen(true);
  };

  // Handle closing the popover
  const handleCloseDialog = () => {
    setDialogOpen(false);
    setNewPostContent("");
  };

  // Handle Snackbar close
  const handleSnackbarClose = (event, reason) => {
    if (reason === "clickaway") {
      return;
    }
    setSnackbarOpen(false);
  };

  // Handle posting new content
  const handlePostContent = (content = newPostContent, files = selectedImages) => {
    const trimmedContent = content.trim();

    if (!trimmedContent) {
      return;
    }

    const optimisticPost = buildOptimisticPost(trimmedContent, files);
    setPosts((prevPosts) => [optimisticPost, ...prevPosts]);
    handleCloseDialog();

    createPost(trimmedContent, files.map((img) => img.file).filter(Boolean))
      .then((response) => {
        const createdPost = response?.data?.result;
        if (createdPost) {
          setPosts((prevPosts) =>
            prevPosts.map((post) =>
              post.postId === optimisticPost.postId
                ? normalizePost({
                    ...optimisticPost,
                    ...createdPost,
                    images: createdPost.images?.length ? createdPost.images : optimisticPost.images,
                    files: createdPost.files?.length ? createdPost.files : optimisticPost.files,
                  })
                : post
            )
          );
        }

        setNewPostContent("");
        setSnackbarMessage("Post created successfully!");
        setSnackbarSeverity("success");
        setSnackbarOpen(true);
      })
      .catch((error) => {
        console.error("Error creating post:", error);
        setSnackbarMessage("Failed to create post. Please try again.");
        setSnackbarSeverity("error");
        setSnackbarOpen(true);
      })
      .finally(() => {
        handleCloseDialog();
      });
  };

  useEffect(() => {
    if (!isAuthenticated()) {
      navigate("/login");
    }
  }, [navigate]);



  const loadPosts = async (checkpoint) => {
    setLoading(true);
    setFeedError(null);
    try {
      const response = await getMyFeed(checkpoint);
      const incomingPosts = response?.data?.result?.data || [];
      setPosts((prevPosts) => {
        const existingIds = new Set(prevPosts.map((post) => post.postId));
        const newPosts = incomingPosts.map(normalizePost).filter(
          (post) => !existingIds.has(post.postId)
        );

        setHasMore(newPosts.length > 0);

        if (newPosts.length > 0) {
          checkpointRef.current = newPosts[newPosts.length - 1].score || newPosts[newPosts.length - 1].postId;
        }

        return [...prevPosts, ...newPosts];
      });
    } catch (error) {
      console.error("Error loading feed:", error);
      setFeedError("Unable to load the feed right now.");
      setSnackbarMessage("Không thể tải bảng tin, vui lòng thử lại sau.");
      setSnackbarSeverity("error");
      setSnackbarOpen(true);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (!hasMore) return;
    if (observer.current) observer.current.disconnect();

    observer.current = new IntersectionObserver((entries) => {
      if (entries[0].isIntersecting && checkpointRef.current) {
        loadPosts(checkpointRef.current);
      }
    });

    if (lastPostElementRef.current) {
      observer.current.observe(lastPostElementRef.current);
    }

    setHasMore(false);
  }, [hasMore]);



  useEffect(() => {
    const readObserver = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            const postId = entry.target.getAttribute("data-id");
            console.log("Đang check entry:", entry.target, "data-id:", entry.target.getAttribute("data-id"));
            if (postId && !readQueueRef.current.includes(postId)) {
              readQueueRef.current.push(postId);
            }
          }
        });
      },
      { threshold: 0.7 }
    );

    document.querySelectorAll(".post-card").forEach((el) => {
      readObserver.observe(el);
    });

    const interval = setInterval(() => {
      if (readQueueRef.current.length > 0) {
        const batch = [...readQueueRef.current];
        readQueueRef.current = [];
        console.log(batch)
          markReadPosts(batch)
            .then(() => {
              console.log("Marked read posts:", batch);
              setReadPosts((prev) => Array.from(new Set([...prev, ...batch])));
            })
            .catch((error) => {
              console.error("Failed to mark read posts:", error);
            });
      }
    }, 2000);

    return () => {
      clearInterval(interval);
      readObserver.disconnect()
    };
  }, [posts]);


  // useEffect(() => {
  //   const checkpointObserver = new IntersectionObserver(
  //     (entries) => {
  //       entries.forEach((entry) => {
  //         if (entry.isIntersecting) {
  //           const postId = entry.target.getAttribute("data-id");
  //           if (postId) {
  //             console.log("✅ Update checkpoint:", postId);
  //             updateCheckpoint(postId).catch(console.error);
  //           }
  //         }
  //       });
  //     },
  //     { threshold: 1.0 } // chỉ khi bài cuối cùng hiển thị 100%
  //   );

  //   const postsEl = document.querySelectorAll(".post-card");
  //   if (postsEl.length > 0) {
  //     const lastVisible = postsEl[postsEl.length - 1];
  //     checkpointObserver.observe(lastVisible);
  //   }

  //   return () => checkpointObserver.disconnect();
  // }, [posts]);




  useEffect(() => {
    if (readPosts.length > 0) {
      const readPostsData = posts.filter(p => readPosts.includes(p.postId?.toString()));
      console.log("Chi tiết các post đã đọc:", readPostsData);
    }
  }, [readPosts, posts]);
  return (
    <Scene sideMenu={<SideMenu />}>
      {" "}
      <Snackbar
        open={snackbarOpen}
        autoHideDuration={6000}
        onClose={handleSnackbarClose}
        anchorOrigin={{ vertical: "top", horizontal: "right" }}
        sx={{ marginTop: "64px" }}
      >
        <Alert
          onClose={handleSnackbarClose}
          severity={snackbarSeverity}
          sx={{ width: "100%" }}
        >
          {snackbarMessage}
        </Alert>
      </Snackbar>
      <Card
        sx={{
          minWidth: 500,
          maxWidth: 600,
          boxShadow: 3,
          borderRadius: 2,
          mt: "20px",
          padding: "20px",
        }}
      >
        <Box
          sx={{
            display: "flex",
            flexDirection: "column",
            alignItems: "flex-start",
            width: "100%",
            gap: "10px",
            justifyContent: "center",
          }}
        >

          <DraggableDialog
            open={dialogOpen}
            onOpen={handleCreatePostClick}
            onClose={handleCloseDialog}
            newPostContent={newPostContent}
            setNewPostContent={setNewPostContent}
            setSelectedImages={setSelectedImages}
            selectedImages={selectedImages}
            onPost={handlePostContent}
          />

          <Typography
            sx={{
              fontSize: 18,
              mb: "10px",
            }}
          >
          </Typography>
          <Box
            sx={{
              display: "flex",
              flexDirection: "row",
              justifyContent: "space-between",
              alignItems: "flex-start",
              width: "100%", // Ensure content takes full width
            }}
          ></Box>
          {/* {posts.map((post, index) => {
            if (posts.length === index + 1) {
              return (
                <Post ref={lastPostElementRef} key={post.id} post={post} />
              );
            } else {
              return <Post key={post.id} post={post} />;
            }
          })} */}
          {feedError && !loading && (
            <Alert
              severity="warning"
              sx={{ mb: 2 }}
              action={
                <Button color="inherit" size="small" onClick={() => loadPosts(null)}>
                  Retry
                </Button>
              }
            >
              {feedError}
            </Alert>
          )}

          {!feedError && !loading && posts.length === 0 && (
            <Box sx={{ p: 2, textAlign: "center" }}>
              <Typography color="text.secondary">
                No posts available right now.
              </Typography>
            </Box>
          )}

          {posts.map((post, index) => {
            const isLast = posts.length === index + 1;
            const isRead = readPosts.includes(post.postId?.toString());
            const PostCard = (
              <Card
                key={post.postId}
                data-id={post.postId}
                className="post-card"
                sx={{
                  width: "95%",
                  p: 2,
                  mb: 2,
                  borderRadius: 3,
                  boxShadow: 2,
                }}>
                <Box sx={{ display: "flex", alignItems: "center", mb: 1 }}>
                  <Avatar
                    src={post.avatarUrl || ""}
                    alt={post.name}
                  />
                  <Box sx={{ ml: 1 }}>
                      <Typography fontWeight="bold">{post.name || post.authorName}</Typography>
                    <Typography variant="caption" color="text.secondary">
                        {post.timestamp || new Date(post.createdDate).toLocaleString()}
                    </Typography>
                  </Box>
                </Box>

                <Typography sx={{ mb: 1 }}>{post.content}</Typography>

                  {((post.images && post.images.length > 0) || (post.files && post.files.length > 0)) && (
                  <Box sx={{ display: "flex", flexDirection: "column", gap: 1, mt: 1 }}>
                      {(post.images?.length ? post.images : post.files.map((file) => file.url).filter(Boolean)).map((imageUrl, idx) => (
                      <Box
                        key={idx}
                        component="img"
                          src={imageUrl}
                        alt={`Ảnh ${idx + 1}`}
                          onClick={() => handleImageClick(post.images?.length ? post.images : post.files.map((file) => file.url).filter(Boolean), idx)}
                        sx={{
                          width: "100%",
                          borderRadius: 2,
                          objectFit: "cover",
                          cursor: "pointer",
                          transition: "0.3s",
                          "&:hover": { opacity: 0.8 }
                        }}
                      />
                    ))}
                  </Box>
                )}
                {isRead && (
                  <Typography
                    variant="caption"
                    color="primary"
                    sx={{ position: "absolute", top: 8, right: 12 }}
                  >
                    Đã đọc
                  </Typography>
                )}
                <Box
                  sx={{
                    display: "flex",
                    justifyContent: "space-around",
                    alignItems: "center",
                    mt: 1,
                    borderTop: "1px solid #eee",
                    pt: 1,
                  }}
                >
                  <Box
                    onClick={() => handleLike(post.postId)}
                    sx={{
                      display: "flex",
                      alignItems: "center",
                      gap: 0.5,
                      cursor: "pointer",
                      color: post.liked ? "red" : "text.secondary",
                      "&:hover": { color: "red" },
                    }}
                  >
                    ❤️
                    <Typography variant="body2">{post.likeCount || 0}</Typography>
                  </Box>

                  <Box
                    onClick={() => handleOpenComments(post)}
                    sx={{
                      display: "flex",
                      alignItems: "center",
                      gap: 0.5,
                      cursor: "pointer",
                      color: "text.secondary",
                      "&:hover": { color: "primary.main" },
                    }}
                  >
                    💬
                    <Typography variant="body2">{post.commentCount || 0} bình luận</Typography>
                  </Box>
                </Box>
              </Card>
            );
            return isLast ? (
              <div key={post.postId} style={{ width: "100%" }} ref={lastPostElementRef}>{PostCard}</div>
            ) : (
              PostCard
            );
          })}

          {loading && (
            <Box
              sx={{ display: "flex", justifyContent: "center", width: "100%" }}
            >
              <CircularProgress size="24px" />
            </Box>
          )}
        </Box>
      </Card>
      <Dialog
        open={previewOpen}
        onClose={handleClosePreview}
        maxWidth="md"
        fullWidth
        PaperProps={{
          sx: { backgroundColor: "black", color: "white", position: "relative" },
        }}
      >
        {previewImages.length > 0 && (
          <Box sx={{ display: "flex", flexDirection: "column", alignItems: "center" }}>
            <Box
              component="img"
              src={previewImages[currentImageIndex]}
              alt="Preview"
              sx={{
                width: "100%",
                height: "auto",
                maxHeight: "80vh",
                objectFit: "contain",
                borderRadius: 2,
              }}
            />

            {/* Nút điều hướng trái/phải */}
            <Box
              sx={{
                position: "absolute",
                top: "50%",
                left: 16,
                transform: "translateY(-50%)",
                cursor: "pointer",
                fontSize: 40,
                color: "white",
                userSelect: "none",
              }}
              onClick={handlePrevImage}
            >
              ‹
            </Box>
            <Box
              sx={{
                position: "absolute",
                top: "50%",
                right: 16,
                transform: "translateY(-50%)",
                cursor: "pointer",
                fontSize: 40,
                color: "white",
                userSelect: "none",
              }}
              onClick={handleNextImage}
            >
              ›
            </Box>

            <Typography variant="caption" sx={{ mt: 1, opacity: 0.7 }}>
              {currentImageIndex + 1} / {previewImages.length}
            </Typography>
          </Box>
        )}
      </Dialog>


      <Dialog
        open={commentDialogOpen}
        onClose={handleCloseComments}
        fullWidth
        maxWidth="sm"
        PaperProps={{
          sx: {
            borderRadius: 3,
            maxHeight: "70vh",
            display: "flex",
            flexDirection: "column",
            overflow: "hidden",
          },
        }}
      >
        {selectedPost && (
          <Box sx={{ display: "flex", flexDirection: "column", height: "100%" }}>
            <Box sx={{ p: 2, borderBottom: "1px solid #eee" }}>
              <Typography fontWeight="bold">{selectedPost.name}</Typography>
              <Typography>{selectedPost.content}</Typography>
            </Box>

            {/* Danh sách comment */}
            <Box sx={{ flex: 1, overflowY: "auto", p: 2 }}>
              {/* map comments here */}
            </Box>

            {/* Ô nhập comment */}
            <Box
              component="form"
              onSubmit={(e) => {
                e.preventDefault();
                console.log("send comment");
              }}
              sx={{
                display: "flex",
                gap: 1,
                p: 1,
                borderTop: "1px solid #eee",
              }}
            >
              <input
                placeholder="Viết bình luận..."
                style={{
                  flex: 1,
                  padding: "10px 14px",
                  borderRadius: "20px",
                  border: "1px solid #ccc",
                  outline: "none",
                }}
              />
              <Button
                type="submit"
                style={{
                  backgroundColor: "#1877f2",
                  color: "white",
                  border: "none",
                  borderRadius: "20px",
                  padding: "8px 14px",
                  cursor: "pointer",
                }}
              >
                Gửi
              </Button>
            </Box>
          </Box>
        )}
      </Dialog>
    </Scene>
  );
}