import httpClient from "../configurations/httpClient";
import { API } from "../configurations/configuration";
import { getToken } from "./localStorageService";

const buildAuthHeaders = () => ({
  Authorization: `Bearer ${getToken()}`,
});

const withRequestWarning = async (operation, request) => {
  try {
    return await request();
  } catch (error) {
    console.warn(`[chatService] ${operation} failed`, error);
    throw error;
  }
};

export const getMyConversations = async () => {
  return await withRequestWarning("getMyConversations", () => httpClient.get(API.MY_CONVERSATIONS, {
    headers: buildAuthHeaders(),
  }));
};

export const createConversation = async (data) => {
  return await withRequestWarning("createConversation", () => httpClient.post(
    API.CREATE_CONVERSATION,
    {
      type: data.type,
      participantIds: data.participantIds,
    },
    {
      headers: {
        ...buildAuthHeaders(),
        "Content-Type": "application/json",
      },
    }
  ));
};


export const createMessage = async (data) => {
  return await withRequestWarning("createMessage", () => httpClient.post(
    API.CREATE_MESSAGE,
    {
      conversationId: data.conversationId,
      message: data.message,
    },
    {
      headers: {
        ...buildAuthHeaders(),
        "Content-Type": "application/json",
      },
    }
  ));
};

export const getMessages = async (conversationId) => {
  return await withRequestWarning("getMessages", () => httpClient.get(`${API.GET_CONVERSATION_MESSAGES}?conversationId=${conversationId}`, {
    headers: buildAuthHeaders(),
  }));
};